changeSet.sql:
SET @old_column_exists = (SELECT COUNT(*) FROM information_schema.columns 
                         WHERE table_schema = DATABASE() 
                         AND table_name = 'm_partial_writeoff_audit' 
                         AND column_name = 'created_date');
SET @sql = IF(@old_column_exists > 0, 
    'ALTER TABLE m_partial_writeoff_audit CHANGE COLUMN created_date created_on_utc TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL', 
    'SELECT "Column created_date does not exist or already renamed"');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @old_column_exists = (SELECT COUNT(*) FROM information_schema.columns 
                         WHERE table_schema = DATABASE() 
                         AND table_name = 'm_partial_writeoff_audit' 
                         AND column_name = 'last_modified_date');
SET @sql = IF(@old_column_exists > 0, 
    'ALTER TABLE m_partial_writeoff_audit CHANGE COLUMN last_modified_date last_modified_on_utc TIMESTAMP', 
    'SELECT "Column last_modified_date does not exist or already renamed"');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @fk_exists = (SELECT COUNT(*) FROM information_schema.table_constraints 
                WHERE constraint_schema = DATABASE() 
                AND table_name = 'm_partial_writeoff_audit' 
                AND constraint_name = 'fk_partial_writeoff_audit_loan');
SET @sql = IF(@fk_exists = 0, 
    'ALTER TABLE m_partial_writeoff_audit ADD CONSTRAINT fk_partial_writeoff_audit_loan FOREIGN KEY (loan_id) REFERENCES m_loan(id)', 
    'SELECT "Constraint fk_partial_writeoff_audit_loan already exists"');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

